def solve(coins, amount):
    # DP for minimum coins (unbounded)
    # Edge case: amount zero
    if amount == 0:
        return 0
    # Initialize dp array with a large sentinel
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        if coin <= 0:
            continue  # ignore non-positive coins
        for x in range(coin, amount + 1):
            if dp[x - coin] + 1 < dp[x]:
                dp[x] = dp[x - coin] + 1
    return dp[amount] if dp[amount] != INF else -1

