def solve(path: str) -> str:
    """Simplify an absolute Unix file path.

    The algorithm uses a stack to process the components split by '/'.
    - Skip empty components and '.' (current directory).
    - For '..' pop the stack if possible (move to parent directory).
    - Otherwise push the component onto the stack.
    The result is '/' joined with the stack contents. If the stack is
    empty, the simplified path is the root '/'.
    """
    if not isinstance(path, str):
        raise TypeError('path must be a string')
    stack = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    return '/' if not stack else '/' + '/'.join(stack)

