def solve(nums):
    """Return length of the longest strictly increasing subsequence.
    Uses patience sorting with binary search (O(n log n)).
    """
    import bisect
    tail = []  # tail[i] = smallest possible tail of an increasing subsequence of length i+1
    for x in nums:
        # find position to replace in tail
        idx = bisect.bisect_left(tail, x)
        if idx == len(tail):
            tail.append(x)
        else:
            tail[idx] = x
    return len(tail)

