def solve(n):
    """Return number of primes strictly less than n using sieve of Eratosthenes."""
    if n <= 2:
        return 0
    # sieve of size n (index up to n-1)
    size = n
    is_prime = bytearray(b'\x01') * size
    is_prime[0:2] = b'\x00\x00'  # 0 and 1 not prime
    import math
    limit = int(math.isqrt(n - 1))
    for p in range(2, limit + 1):
        if is_prime[p]:
            step = p
            start = p * p
            is_prime[start:n:step] = b'\x00' * ((n - 1 - start) // step + 1)
    return sum(is_prime)

