def solve(line: str):
    """Parse a single CSV line according to the simplified rules.
    Returns a list of fields. Empty line yields [''].
    """
    if line == "":
        return [""]
    fields = []
    i = 0
    n = len(line)
    while i < n:
        if line[i] == '"':
            # quoted field
            i += 1
            sb = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i+1] == '"':
                        sb.append('"')
                        i += 2
                    else:
                        i += 1  # consume closing quote
                        break
                else:
                    sb.append(line[i])
                    i += 1
            field = ''.join(sb)
        else:
            sb = []
            while i < n and line[i] != ',':
                sb.append(line[i])
                i += 1
            field = ''.join(sb)
        fields.append(field)
        # skip delimiter if present
        if i < n and line[i] == ',':
            i += 1
    # handle trailing comma producing empty field
    if line and line[-1] == ',':
        fields.append('')
    return fields

