def solve(meetings):
    """Return the maximum number of non‑overlapping meetings.
    Each meeting is a list/tuple [start, end]. If a meeting is given with start > end, it is treated as having its
    endpoints swapped (i.e., the interval is still valid). Meetings may touch at endpoints.
    Greedy algorithm: sort by increasing end time, then select compatible meetings.
    """
    if not meetings:
        return 0
    # Normalize intervals so that start <= end
    normalized = []
    for m in meetings:
        if len(m) < 2:
            continue
        a, b = m[0], m[1]
        if a <= b:
            start, end = a, b
        else:
            start, end = b, a
        normalized.append((start, end))
    if not normalized:
        return 0
    # Sort by end, then start for deterministic tie-breaking
    normalized.sort(key=lambda interval: (interval[1], interval[0]))
    count = 0
    current_end = -float('inf')
    for start, end in normalized:
        if start >= current_end:
            count += 1
            current_end = end
    return count

