def solve(coins, amount):
    """Return the minimum number of coins needed to make *amount* with unlimited supply.
    Coins with non‑positive value are ignored. If impossible, return -1.
    """
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # filter out non‑positive coins
    coins = [c for c in coins if c > 0]
    if not coins:
        return -1
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                if dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

