def solve(line: str):
    """Parse a single CSV line according to the problem specification.
    Fields may be quoted with double quotes. Inside quotes, commas are literal and a
    doubled quote represents a single quote character. The function returns a list
    of field strings. An empty input line yields [''].
    """
    # Fast path for empty line
    if line == "":
        return ['']
    # Try using the csv module which implements the required quoting rules.
    # It handles most edge cases, but we guard against malformed input that could
    # raise csv.Error by falling back to a manual parser.
    import csv
    try:
        return next(csv.reader([line]))
    except Exception:
        # Manual parsing fallback
        fields = []
        i, n = 0, len(line)
        while i < n:
            if line[i] == '"':
                # Quoted field
                i += 1
                sb = []
                while i < n:
                    if line[i] == '"':
                        if i + 1 < n and line[i + 1] == '"':
                            sb.append('"')
                            i += 2
                        else:
                            i += 1  # closing quote
                            break
                    else:
                        sb.append(line[i])
                        i += 1
                field = ''.join(sb)
            else:
                # Unquoted field
                sb = []
                while i < n and line[i] != ',':
                    sb.append(line[i])
                    i += 1
                field = ''.join(sb)
            fields.append(field)
            # Skip delimiter if present
            if i < n and line[i] == ',':
                i += 1
        # If line ends with a comma, CSV semantics dictate a trailing empty field
        if line and line[-1] == ',':
            fields.append('')
        return fields

